def slug(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')[:110]
def select(label,opts,demo,help_text=None):
 d={'label':label,'type':'select','required':False,'options':[{'value':v,'label':l} for v,l in opts],'demo_value':demo}
 if help_text:d['help_text']=help_text
 return d
def num(label,demo,unit='',step=.1,minv=0,maxv=None):
 d={'label':label,'type':'number','required':False,'min':minv,'step':step,'demo_value':demo}
 if unit:d['unit']=unit
 if maxv is not None:d['max']=maxv
 return d
def boolean(label,demo=False,help_text=None):
 d={'label':label,'type':'boolean','required':False,'demo_value':demo}
 if help_text:d['help_text']=help_text
 return d
def grade(label,cat='other_nonhaematological'):
 desc=['No toxicity.','Mild or asymptomatic; observation only.','Moderate; intervention may be indicated and instrumental activities may be limited.','Severe or medically significant; self-care activities may be limited.','Life-threatening consequences; urgent intervention required.']
 return {'label':label,'type':'select','required':False,'options':[{'value':i,'label':f'Grade {i}','ctcae_grade':i,'description':desc[i]} for i in range(5)],'demo_value':0,'ctcae_version':'5.0','ctcae_category':cat,'ctcae_source_url':CTCAE,'assessment_guidance':'Grade the named toxicity using symptoms, objective findings, intervention required and functional impact.'}
def rule(rid,field,op,value,action,msg,priority=8,components=None,page='Dose modifications / assessment'):
 return {'id':rid,'priority':priority,'when':{'field':field,'operator':op,'value':value},'action':{'type':action,'components':components or ['whole_regimen'],'message':msg},'source':{'document':'Current official NCCP regimen','page':page},'explanation':msg}

def base_inputs():
 return {'assessment_phase':select('Assessment phase',[('pre_treatment','Pre-treatment'),('on_treatment','On-treatment'),('toxicity_review','Toxicity review')],'pre_treatment'),'ecog':select('ECOG performance status',[(i,str(i)) for i in range(5)],1),'anc':num('ANC',2,'×10⁹/L',.01),'platelets':num('Platelets',180,'×10⁹/L',1),'haemoglobin':num('Haemoglobin',12,'g/dL',.1),'alt_ast_uln_multiple':num('ALT / AST actual result (highest ×ULN calculated automatically)',1,'×ULN',.01),'bilirubin_uln_multiple':num('Bilirubin actual result (×ULN calculated automatically)',1,'×ULN',.01),'non_haematological_toxicity_grade':grade('Other clinically relevant non-haematological toxicity grade'),'febrile_neutropenia':boolean('Febrile neutropenia or neutropenic sepsis'),'hypersensitivity':boolean('Known hypersensitivity to a regimen component'),'pregnancy':boolean('Pregnant'),'breastfeeding':boolean('Breastfeeding')}
def base_rules(cyt=True):
 r=[rule('HYPERSENSITIVITY','hypersensitivity','==',True,'contraindicated','Known clinically significant hypersensitivity to a regimen component triggers the source contraindication.',10),rule('ECOG_3','ecog','>=',3,'consultant_review','ECOG 3–4 requires Consultant review of indication, expected benefit and treatment tolerance.',8),rule('NONHAEM_G3','non_haematological_toxicity_grade','>=',3,'withhold','Grade 3 or worse treatment-related non-haematological toxicity requires treatment interruption and protocol-specific review.',9)]
 if cyt:r.append(rule('FN','febrile_neutropenia','==',True,'withhold_then_reduce','Febrile neutropenia requires acute management, treatment delay and source-directed dose/G-CSF review.',10))
 return r

def add_platinum(inp,rules,drugs):
 if 'carboplatin' in drugs:
  inp['gfr_or_crcl_ml_min']=num('Measured GFR or protocol-approved CrCl',80,'mL/min',1)
  inp['gfr_or_crcl_ml_min']['renal_input']={'mode':'exact_continuous','exact_value_required':True,'reason':'Exact GFR/CrCl is used for Calvert dosing and renal review.'}
  rules.append(rule('CARBO_GFR_LE20','gfr_or_crcl_ml_min','<=',20,'contraindicated','GFR/CrCl ≤20 mL/min: carboplatin is not recommended in the encoded NCCP pathway.',10,['carboplatin']))
 if 'cisplatin' in drugs:
  inp['cisplatin_crcl_band']=select('Renal function for cisplatin',[('ge60','CrCl ≥60 mL/min'),('50_59','50–59 mL/min'),('45_59','45–59 mL/min where specified'),('40_49','40–49 mL/min'),('lt45','<45 mL/min'),('lt40','<40 mL/min'),('dialysis','Haemodialysis')],'ge60')
  inp['cisplatin_neuro_hearing_grade']=grade('Cisplatin-related neuropathy, tinnitus or hearing toxicity grade','neuropathy')
  inp['electrolytes_hydration_not_corrected']=boolean('Required hydration/electrolyte correction incomplete')
  rules += [rule('CIS_RENAL_50_59','cisplatin_crcl_band','in',['50_59','45_59'],'dose_reduce','Reduced renal function requires the source-specific cisplatin reduction or substitution pathway.',9,['cisplatin']),rule('CIS_RENAL_40_49','cisplatin_crcl_band','==','40_49','dose_reduce','CrCl 40–49 mL/min requires major cisplatin reduction or alternative treatment according to the source.',10,['cisplatin']),rule('CIS_RENAL_LOW','cisplatin_crcl_band','in',['lt45','lt40','dialysis'],'contraindicated','Severe renal impairment triggers the source pathway in which cisplatin is not recommended without specialist direction.',10,['cisplatin']),rule('CIS_NEURO_G2','cisplatin_neuro_hearing_grade','>=',2,'consultant_review','Grade 2 or worse neuro/hearing toxicity requires cisplatin dose, omission or substitution review.',9,['cisplatin']),rule('CIS_HYDRATION','electrolytes_hydration_not_corrected','==',True,'withhold','Correct hydration and electrolytes before cisplatin.',9,['cisplatin'])]
def add_5fu(inp,rules):
 inp['dpd_status']=select('DPD status',[('normal','Normal / no clinically relevant deficiency identified'),('partial','Partial DPD deficiency'),('complete','Complete DPD deficiency'),('unknown','Unknown / not available')],'normal')
 inp['bilirubin_umol_l']=num('Bilirubin',12,'µmol/L',1)
 inp['ast_u_l']=num('AST',25,'U/L',1)
 inp['mucositis_grade']=grade('Mucositis/stomatitis grade','mucositis')
 rules += [rule('DPD_COMPLETE','dpd_status','==','complete','contraindicated','Complete DPD deficiency: fluorouracil is contraindicated.',10,['fluorouracil']),rule('DPD_PARTIAL','dpd_status','==','partial','dose_reduce','Partial DPD deficiency requires an individualised reduced fluorouracil starting dose and close monitoring.',10,['fluorouracil']),rule('5FU_HEPATIC','bilirubin_umol_l','>',85,'contraindicated','Bilirubin >85 µmol/L triggers the encoded fluorouracil contraindication.',10,['fluorouracil']),rule('5FU_AST','ast_u_l','>',180,'contraindicated','AST >180 U/L triggers the encoded fluorouracil contraindication.',10,['fluorouracil']),rule('5FU_MUC_G2','mucositis_grade','>=',2,'withhold','Grade 2 or worse mucositis requires treatment interruption and source-directed recovery/dose review.',9,['fluorouracil'])]
def add_cetux(inp,rules):
 inp['cetuximab_infusion_reaction_grade']=grade('Cetuximab infusion-reaction grade','infusion_reaction')
